namespace Acs.Core.Storage;

/// <summary>Schema v1 as a constant (an embedded Schema.sql would need a csproj edit).</summary>
internal static class Schema
{
    public const int Version = 3;

    public const string V1 = """
CREATE TABLE devices(
  id INTEGER PRIMARY KEY, name TEXT NOT NULL, host TEXT NOT NULL, username TEXT NOT NULL, password BLOB NOT NULL,
  door_no INTEGER NOT NULL DEFAULT 1, is_capture_default INTEGER NOT NULL DEFAULT 0, is_finger_reader INTEGER NOT NULL DEFAULT 0,
  model TEXT, serial TEXT, firmware TEXT, fp_group TEXT NOT NULL, auth_paused INTEGER NOT NULL DEFAULT 0,
  last_seen TEXT, created_at TEXT NOT NULL);
CREATE TABLE groups(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL);
CREATE TABLE people(
  employee_no TEXT PRIMARY KEY, full_name TEXT NOT NULL, group_id INTEGER REFERENCES groups(id) ON DELETE SET NULL,
  valid_from TEXT NOT NULL, valid_to TEXT NULL, status TEXT NOT NULL DEFAULT 'active',
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL, locked_at TEXT NULL);
CREATE TABLE faces(
  employee_no TEXT PRIMARY KEY REFERENCES people(employee_no) ON DELETE CASCADE,
  jpeg BLOB NOT NULL, source TEXT NOT NULL, captured_at TEXT NOT NULL);
CREATE TABLE fingerprints(
  employee_no TEXT NOT NULL REFERENCES people(employee_no) ON DELETE CASCADE,
  finger_id INTEGER NOT NULL CHECK(finger_id BETWEEN 1 AND 10), fp_group TEXT NOT NULL, template BLOB NOT NULL,
  quality INTEGER, source TEXT NOT NULL, captured_at TEXT NOT NULL, PRIMARY KEY(employee_no, finger_id, fp_group));
CREATE TABLE device_state(
  employee_no TEXT NOT NULL REFERENCES people(employee_no) ON DELETE CASCADE,
  device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  user_present INTEGER NOT NULL DEFAULT 0, user_enabled INTEGER NOT NULL DEFAULT 0, face_present INTEGER NOT NULL DEFAULT 0,
  fingers TEXT NOT NULL DEFAULT '', needs_scan TEXT NOT NULL DEFAULT '', verified_at TEXT,
  PRIMARY KEY(employee_no, device_id));
CREATE TABLE jobs(
  id INTEGER PRIMARY KEY, device_id INTEGER NOT NULL REFERENCES devices(id) ON DELETE CASCADE,
  employee_no TEXT NOT NULL, kind TEXT NOT NULL, finger_id INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending',
  attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL, error_kind TEXT, error_message TEXT, error_detail TEXT,
  created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX jobs_open ON jobs(device_id, employee_no, kind, finger_id) WHERE status IN ('pending','running','failed');
CREATE TABLE log(id INTEGER PRIMARY KEY, at TEXT NOT NULL, employee_no TEXT, device_id INTEGER, action TEXT NOT NULL, ok INTEGER NOT NULL, message TEXT);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT);
""";

    /// <summary>
    /// v2 (0.9.10): people.draft = created in the app and not sent yet (no face, no finger); Thùng rác. Existing people
    /// count as drafts only when nothing ever went to a device for them: no face, no finger, no device state, no job.
    /// </summary>
    public const string V2 = """
ALTER TABLE people ADD COLUMN draft INTEGER NOT NULL DEFAULT 0;
CREATE TABLE trash(
  id INTEGER PRIMARY KEY, employee_no TEXT NOT NULL, full_name TEXT NOT NULL, group_name TEXT,
  has_face INTEGER NOT NULL DEFAULT 0, finger_count INTEGER NOT NULL DEFAULT 0, deleted_at TEXT NOT NULL, data BLOB NOT NULL);
UPDATE people SET draft=1
 WHERE NOT EXISTS (SELECT 1 FROM faces f WHERE f.employee_no=people.employee_no)
   AND NOT EXISTS (SELECT 1 FROM fingerprints f WHERE f.employee_no=people.employee_no)
   AND NOT EXISTS (SELECT 1 FROM device_state s WHERE s.employee_no=people.employee_no)
   AND NOT EXISTS (SELECT 1 FROM jobs j WHERE j.employee_no=people.employee_no);
""";

    /// <summary>
    /// v3 (0.9.15, Dữ liệu chung): outbox of changed natural keys (filled by triggers only while capture is on), the
    /// cloud version last seen per key, rows waiting for a device they reference, and which PC / origin wrote each
    /// log line. Natural key parts are joined with U+001F.
    /// </summary>
    public const string V3 = """
CREATE TABLE outbox(tbl TEXT NOT NULL, k TEXT NOT NULL, gen INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tbl, k));
CREATE TABLE sync_rows(tbl TEXT NOT NULL, k TEXT NOT NULL, rid TEXT NOT NULL, ver INTEGER NOT NULL, PRIMARY KEY(tbl, k));
CREATE TABLE sync_deferred(tbl TEXT NOT NULL, rid TEXT NOT NULL, ver INTEGER NOT NULL, deleted INTEGER NOT NULL, data TEXT, PRIMARY KEY(tbl, rid));
CREATE TABLE sync_flags(name TEXT PRIMARY KEY, on_ INTEGER NOT NULL);
INSERT INTO sync_flags(name, on_) VALUES('capture', 0);
ALTER TABLE log ADD COLUMN pc TEXT;
ALTER TABLE log ADD COLUMN origin TEXT;
UPDATE log SET origin = lower(hex(randomblob(16))) WHERE origin IS NULL;
CREATE TRIGGER ob_people_i AFTER INSERT ON people WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND NEW.draft=0 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='people' AND k=NEW.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'people', NEW.employee_no, 0 WHERE NEW.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='people' AND k=NEW.employee_no); END;
CREATE TRIGGER ob_people_u AFTER UPDATE ON people WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='people' AND k=OLD.employee_no AND (OLD.employee_no IS NOT NEW.employee_no AND OLD.draft=0); INSERT INTO outbox(tbl, k, gen) SELECT 'people', OLD.employee_no, 0 WHERE OLD.employee_no IS NOT NULL AND (OLD.employee_no IS NOT NEW.employee_no AND OLD.draft=0) AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='people' AND k=OLD.employee_no); UPDATE outbox SET gen=gen+1 WHERE tbl='people' AND k=NEW.employee_no AND (NEW.draft=0); INSERT INTO outbox(tbl, k, gen) SELECT 'people', NEW.employee_no, 0 WHERE NEW.employee_no IS NOT NULL AND (NEW.draft=0) AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='people' AND k=NEW.employee_no); END;
CREATE TRIGGER ob_people_d AFTER DELETE ON people WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND OLD.draft=0 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='people' AND k=OLD.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'people', OLD.employee_no, 0 WHERE OLD.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='people' AND k=OLD.employee_no); END;
CREATE TRIGGER ob_groups_i AFTER INSERT ON groups WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='groups' AND k=NEW.name; INSERT INTO outbox(tbl, k, gen) SELECT 'groups', NEW.name, 0 WHERE NEW.name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='groups' AND k=NEW.name); END;
CREATE TRIGGER ob_groups_u AFTER UPDATE ON groups WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='groups' AND k=OLD.name; INSERT INTO outbox(tbl, k, gen) SELECT 'groups', OLD.name, 0 WHERE OLD.name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='groups' AND k=OLD.name); UPDATE outbox SET gen=gen+1 WHERE tbl='groups' AND k=NEW.name; INSERT INTO outbox(tbl, k, gen) SELECT 'groups', NEW.name, 0 WHERE NEW.name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='groups' AND k=NEW.name); END;
CREATE TRIGGER ob_groups_d AFTER DELETE ON groups WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='groups' AND k=OLD.name; INSERT INTO outbox(tbl, k, gen) SELECT 'groups', OLD.name, 0 WHERE OLD.name IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='groups' AND k=OLD.name); END;
CREATE TRIGGER ob_faces_i AFTER INSERT ON faces WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='faces' AND k=NEW.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'faces', NEW.employee_no, 0 WHERE NEW.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='faces' AND k=NEW.employee_no); END;
CREATE TRIGGER ob_faces_u AFTER UPDATE ON faces WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='faces' AND k=OLD.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'faces', OLD.employee_no, 0 WHERE OLD.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='faces' AND k=OLD.employee_no); UPDATE outbox SET gen=gen+1 WHERE tbl='faces' AND k=NEW.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'faces', NEW.employee_no, 0 WHERE NEW.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='faces' AND k=NEW.employee_no); END;
CREATE TRIGGER ob_faces_d AFTER DELETE ON faces WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='faces' AND k=OLD.employee_no; INSERT INTO outbox(tbl, k, gen) SELECT 'faces', OLD.employee_no, 0 WHERE OLD.employee_no IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='faces' AND k=OLD.employee_no); END;
CREATE TRIGGER ob_fingerprints_i AFTER INSERT ON fingerprints WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='fingerprints' AND k=(NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group); INSERT INTO outbox(tbl, k, gen) SELECT 'fingerprints', (NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group), 0 WHERE (NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='fingerprints' AND k=(NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group)); END;
CREATE TRIGGER ob_fingerprints_u AFTER UPDATE ON fingerprints WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='fingerprints' AND k=(OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group); INSERT INTO outbox(tbl, k, gen) SELECT 'fingerprints', (OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group), 0 WHERE (OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='fingerprints' AND k=(OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group)); UPDATE outbox SET gen=gen+1 WHERE tbl='fingerprints' AND k=(NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group); INSERT INTO outbox(tbl, k, gen) SELECT 'fingerprints', (NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group), 0 WHERE (NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='fingerprints' AND k=(NEW.employee_no || char(31) || NEW.finger_id || char(31) || NEW.fp_group)); END;
CREATE TRIGGER ob_fingerprints_d AFTER DELETE ON fingerprints WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='fingerprints' AND k=(OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group); INSERT INTO outbox(tbl, k, gen) SELECT 'fingerprints', (OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group), 0 WHERE (OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='fingerprints' AND k=(OLD.employee_no || char(31) || OLD.finger_id || char(31) || OLD.fp_group)); END;
CREATE TRIGGER ob_devices_i AFTER INSERT ON devices WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='devices' AND k=NEW.fp_group; INSERT INTO outbox(tbl, k, gen) SELECT 'devices', NEW.fp_group, 0 WHERE NEW.fp_group IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='devices' AND k=NEW.fp_group); END;
CREATE TRIGGER ob_devices_u AFTER UPDATE ON devices WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND (OLD.name IS NOT NEW.name OR OLD.host IS NOT NEW.host OR OLD.username IS NOT NEW.username OR OLD.password IS NOT NEW.password OR OLD.door_no IS NOT NEW.door_no OR OLD.is_capture_default IS NOT NEW.is_capture_default OR OLD.is_finger_reader IS NOT NEW.is_finger_reader OR OLD.fp_group IS NOT NEW.fp_group) BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='devices' AND k=OLD.fp_group; INSERT INTO outbox(tbl, k, gen) SELECT 'devices', OLD.fp_group, 0 WHERE OLD.fp_group IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='devices' AND k=OLD.fp_group); UPDATE outbox SET gen=gen+1 WHERE tbl='devices' AND k=NEW.fp_group; INSERT INTO outbox(tbl, k, gen) SELECT 'devices', NEW.fp_group, 0 WHERE NEW.fp_group IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='devices' AND k=NEW.fp_group); END;
CREATE TRIGGER ob_devices_d AFTER DELETE ON devices WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='devices' AND k=OLD.fp_group; INSERT INTO outbox(tbl, k, gen) SELECT 'devices', OLD.fp_group, 0 WHERE OLD.fp_group IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='devices' AND k=OLD.fp_group); END;
CREATE TRIGGER ob_devices_bd BEFORE DELETE ON devices WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='device_state' AND k IN (SELECT employee_no || char(31) || OLD.fp_group FROM device_state WHERE device_id=OLD.id); INSERT INTO outbox(tbl, k, gen) SELECT 'device_state', employee_no || char(31) || OLD.fp_group, 0 FROM device_state WHERE device_id=OLD.id AND NOT EXISTS (SELECT 1 FROM outbox o WHERE o.tbl='device_state' AND o.k=device_state.employee_no || char(31) || OLD.fp_group); UPDATE outbox SET gen=gen+1 WHERE tbl='jobs' AND k IN (SELECT OLD.fp_group || char(31) || employee_no || char(31) || kind || char(31) || finger_id || char(31) || created_at FROM jobs WHERE device_id=OLD.id); INSERT INTO outbox(tbl, k, gen) SELECT 'jobs', OLD.fp_group || char(31) || employee_no || char(31) || kind || char(31) || finger_id || char(31) || created_at, 0 FROM jobs WHERE device_id=OLD.id AND NOT EXISTS (SELECT 1 FROM outbox o WHERE o.tbl='jobs' AND o.k=OLD.fp_group || char(31) || jobs.employee_no || char(31) || jobs.kind || char(31) || jobs.finger_id || char(31) || jobs.created_at); END;
CREATE TRIGGER ob_device_state_i AFTER INSERT ON device_state WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='device_state' AND k=(NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)); INSERT INTO outbox(tbl, k, gen) SELECT 'device_state', (NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)), 0 WHERE (NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='device_state' AND k=(NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id))); END;
CREATE TRIGGER ob_device_state_u AFTER UPDATE ON device_state WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='device_state' AND k=(OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)); INSERT INTO outbox(tbl, k, gen) SELECT 'device_state', (OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)), 0 WHERE (OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='device_state' AND k=(OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id))); UPDATE outbox SET gen=gen+1 WHERE tbl='device_state' AND k=(NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)); INSERT INTO outbox(tbl, k, gen) SELECT 'device_state', (NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)), 0 WHERE (NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='device_state' AND k=(NEW.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=NEW.device_id))); END;
CREATE TRIGGER ob_device_state_d AFTER DELETE ON device_state WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='device_state' AND k=(OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)); INSERT INTO outbox(tbl, k, gen) SELECT 'device_state', (OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)), 0 WHERE (OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='device_state' AND k=(OLD.employee_no || char(31) || (SELECT fp_group FROM devices WHERE id=OLD.device_id))); END;
