CREATE TRIGGER ob_jobs_u AFTER UPDATE ON jobs WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at); INSERT INTO outbox(tbl, k, gen) SELECT 'jobs', ((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at), 0 WHERE ((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at)); UPDATE outbox SET gen=gen+1 WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=NEW.device_id) || char(31) || NEW.employee_no || char(31) || NEW.kind || char(31) || NEW.finger_id || char(31) || NEW.created_at); INSERT INTO outbox(tbl, k, gen) SELECT 'jobs', ((SELECT fp_group FROM devices WHERE id=NEW.device_id) || char(31) || NEW.employee_no || char(31) || NEW.kind || char(31) || NEW.finger_id || char(31) || NEW.created_at), 0 WHERE ((SELECT fp_group FROM devices WHERE id=NEW.device_id) || char(31) || NEW.employee_no || char(31) || NEW.kind || char(31) || NEW.finger_id || char(31) || NEW.created_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=NEW.device_id) || char(31) || NEW.employee_no || char(31) || NEW.kind || char(31) || NEW.finger_id || char(31) || NEW.created_at)); END;
CREATE TRIGGER ob_jobs_d AFTER DELETE ON jobs WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at); INSERT INTO outbox(tbl, k, gen) SELECT 'jobs', ((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at), 0 WHERE ((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='jobs' AND k=((SELECT fp_group FROM devices WHERE id=OLD.device_id) || char(31) || OLD.employee_no || char(31) || OLD.kind || char(31) || OLD.finger_id || char(31) || OLD.created_at)); END;
CREATE TRIGGER ob_trash_i AFTER INSERT ON trash WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='trash' AND k=(NEW.employee_no || char(31) || NEW.deleted_at); INSERT INTO outbox(tbl, k, gen) SELECT 'trash', (NEW.employee_no || char(31) || NEW.deleted_at), 0 WHERE (NEW.employee_no || char(31) || NEW.deleted_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='trash' AND k=(NEW.employee_no || char(31) || NEW.deleted_at)); END;
CREATE TRIGGER ob_trash_u AFTER UPDATE ON trash WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='trash' AND k=(OLD.employee_no || char(31) || OLD.deleted_at); INSERT INTO outbox(tbl, k, gen) SELECT 'trash', (OLD.employee_no || char(31) || OLD.deleted_at), 0 WHERE (OLD.employee_no || char(31) || OLD.deleted_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='trash' AND k=(OLD.employee_no || char(31) || OLD.deleted_at)); UPDATE outbox SET gen=gen+1 WHERE tbl='trash' AND k=(NEW.employee_no || char(31) || NEW.deleted_at); INSERT INTO outbox(tbl, k, gen) SELECT 'trash', (NEW.employee_no || char(31) || NEW.deleted_at), 0 WHERE (NEW.employee_no || char(31) || NEW.deleted_at) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='trash' AND k=(NEW.employee_no || char(31) || NEW.deleted_at)); END;
