CREATE TRIGGER ob_log_i AFTER INSERT ON log WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND NEW.origin IS NOT NULL BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='log' AND k=NEW.origin; INSERT INTO outbox(tbl, k, gen) SELECT 'log', NEW.origin, 0 WHERE NEW.origin IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='log' AND k=NEW.origin); END;
CREATE TRIGGER ob_settings_i AFTER INSERT ON settings WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND NEW.key='employeeNo.deviceHighWater' BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='settings' AND k=NEW.key; INSERT INTO outbox(tbl, k, gen) SELECT 'settings', NEW.key, 0 WHERE NEW.key IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='settings' AND k=NEW.key); END;
CREATE TRIGGER ob_settings_u AFTER UPDATE ON settings WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND NEW.key='employeeNo.deviceHighWater' BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='settings' AND k=OLD.key; INSERT INTO outbox(tbl, k, gen) SELECT 'settings', OLD.key, 0 WHERE OLD.key IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='settings' AND k=OLD.key); UPDATE outbox SET gen=gen+1 WHERE tbl='settings' AND k=NEW.key; INSERT INTO outbox(tbl, k, gen) SELECT 'settings', NEW.key, 0 WHERE NEW.key IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='settings' AND k=NEW.key); END;
CREATE TRIGGER ob_settings_d AFTER DELETE ON settings WHEN (SELECT on_ FROM sync_flags WHERE name='capture')=1 AND OLD.key='employeeNo.deviceHighWater' BEGIN UPDATE outbox SET gen=gen+1 WHERE tbl='settings' AND k=OLD.key; INSERT INTO outbox(tbl, k, gen) SELECT 'settings', OLD.key, 0 WHERE OLD.key IS NOT NULL AND NOT EXISTS (SELECT 1 FROM outbox WHERE tbl='settings' AND k=OLD.key); END;
